import {describe, it, expect} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

describe('Usage accumulation (acceptance)', () => {
  const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
    result: 'found it',
  }));

  it('accumulates usage across every tool round, not just the last', async () => {
    const usage1: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const usage2: UsageMetadata = {inputTokens: 20, outputTokens: 10, totalTokens: 30};

    const provider = scriptedProvider([
      [TOOL_CALL, {...STOP_FOR_TOOL, usage: usage1}],
      [{type: 'text', text: 'final answer'}, {...STOP_DONE, usage: usage2}],
    ]);

    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('test'));

    // This is expected to FAIL right now because it only reports usage2
    expect(reportedUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });

  it('reports correct usage for a single round turn', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const provider = scriptedProvider([[{type: 'text', text: 'answer'}, {...STOP_DONE, usage}]]);

    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('test'));

    expect(reportedUsage).toEqual(usage);
  });

  it('ignores rounds with missing usage in the total', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL], // No usage here
      [{type: 'text', text: 'answer'}, {...STOP_DONE, usage}],
    ]);

    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('test'));

    expect(reportedUsage).toEqual(usage);
  });
});
